CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, timezone text NOT NULL DEFAULT 'Africa/Nairobi', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, email text NOT NULL, password_hash text NOT NULL, full_name text NOT NULL, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','SCHOOL_ADMIN','PARENT','TEACHER')), active boolean NOT NULL DEFAULT true, invitation_token_hash text, invitation_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,email));
CREATE UNIQUE INDEX IF NOT EXISTS users_global_email_superadmin_idx ON users(lower(email)) WHERE role='SUPER_ADMIN';
CREATE TABLE IF NOT EXISTS students (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, full_name text NOT NULL, class_name text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS students_school_idx ON students(school_id);
CREATE TABLE IF NOT EXISTS parents (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, relationship text);
CREATE TABLE IF NOT EXISTS teachers (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, staff_number text);
CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, name text NOT NULL, operating_system text NOT NULL, extension_version text, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','paused','revoked')), enrollment_code_hash text UNIQUE, enrollment_expires_at timestamptz, device_token_hash text UNIQUE, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS devices_school_idx ON devices(school_id);
CREATE TABLE IF NOT EXISTS device_assignments (device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, assigned_by uuid REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(device_id,student_id));
CREATE TABLE IF NOT EXISTS website_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE CASCADE, name text NOT NULL, description text, UNIQUE(school_id,name));
CREATE TABLE IF NOT EXISTS website_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'website' CHECK(kind='website'), domain text NOT NULL, category text NOT NULL, action text NOT NULL CHECK(action IN ('allow','block')), url_match text NOT NULL DEFAULT 'domain', capture_full_url boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS website_rules_unique ON website_rules(school_id,lower(domain),url_match);
CREATE TABLE IF NOT EXISTS application_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'application' CHECK(kind='application'), name text NOT NULL, category text NOT NULL, action text NOT NULL CHECK(action IN ('allow','block')), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,name));
CREATE TABLE IF NOT EXISTS restriction_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, category text NOT NULL, action text NOT NULL CHECK(action IN ('allow','block','alert')), enabled boolean NOT NULL DEFAULT true, alert_enabled boolean NOT NULL DEFAULT false, created_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(school_id,category));
CREATE TABLE IF NOT EXISTS activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, event_id text NOT NULL, domain text, application_name text, occurred_at timestamptz NOT NULL, duration_seconds integer NOT NULL DEFAULT 0 CHECK(duration_seconds >= 0), access_status text NOT NULL CHECK(access_status IN ('allowed','blocked')), category text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(device_id,event_id), CHECK(domain IS NULL OR length(domain)<=253), CHECK(application_name IS NULL OR length(application_name)<=200));
CREATE INDEX IF NOT EXISTS activity_school_time_idx ON activity_logs(school_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS activity_student_time_idx ON activity_logs(student_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, student_id uuid REFERENCES students(id) ON DELETE SET NULL, kind text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid REFERENCES schools(id) ON DELETE SET NULL, actor_user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_school_time_idx ON audit_logs(school_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL UNIQUE REFERENCES schools(id) ON DELETE CASCADE, plan text NOT NULL DEFAULT 'trial', status text NOT NULL DEFAULT 'active', starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz);
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
